// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 100 ether);
        Attacker att = new Attacker(c);
        vm.deal(address(this), amount);
        att.deposit{value: amount}();
        att.attack();
        bool ok = false;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok, "withdrawAll must succeed for a settled account");
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool private __entered;
    constructor(ReentrancyDAO _c) { c = _c; }
    function deposit() external payable { c.deposit{value: msg.value}(); }
    function attack() external {
        c.withdrawAll();
    }
    receive() external payable {
        if (!__entered) {
            __entered = true;
            c.withdrawAll();
        }
    }
}
